import React, { useState } from "react";

const Home = () => {
  const [search, setSearch] = useState("");

  // Sample professionals list
  const professionals = [
    { name: "Rahul Sharma", category: "Electrician" },
    { name: "Priya Verma", category: "Plumber" },
    { name: "Kiran Kumar", category: "Carpenter" },
    { name: "Sanjay Reddy", category: "Painter" },
    { name: "Anita Desai", category: "Cleaning Service" },
  ];

  // Filter Based on Search
  const filtered = professionals.filter((pro) =>
    pro.name.toLowerCase().includes(search.toLowerCase()) ||
    pro.category.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Find Professionals Near You</h1>

      {/* Search Bar */}
      <input
        type="text"
        placeholder="Search electrician, plumber, carpenter..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={styles.search}
      />

      {/* Professionals List */}
      <div style={styles.listContainer}>
        {filtered.map((pro, index) => (
          <div key={index} style={styles.card}>
            <h3 style={{ marginBottom: "5px" }}>{pro.name}</h3>
            <p style={{ color: "#555" }}>{pro.category}</p>
          </div>
        ))}

        {filtered.length === 0 && (
          <p style={{ marginTop: "20px", color: "white" }}>No professionals found</p>
        )}
      </div>
    </div>
  );
};

// CSS Styles
const styles = {
  container: {
    padding: "40px",
    textAlign: "center",
    background: "linear-gradient(to bottom right, #1e3c72, #2a5298)",
    minHeight: "100vh",
  },
  title: {
    color: "white",
    fontSize: "36px",
    marginBottom: "30px",
  },
  search: {
    width: "60%",
    padding: "12px",
    fontSize: "16px",
    borderRadius: "8px",
    border: "none",
    marginBottom: "30px",
  },
  listContainer: {
    display: "flex",
    justifyContent: "center",
    flexWrap: "wrap",
    gap: "20px",
  },
  card: {
    background: "white",
    width: "250px",
    padding: "20px",
    borderRadius: "12px",
    boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
    textAlign: "center",
  },
};

export default Home;
